function attSelect(string $name,string $label,array $options,mixed $selected='',bool $required=false):void{echo '<label>'.e($label).'<select name="'.e($name).'" '.($required?'required':'').'><option value="">'.($required?'Select…':'All').'</option>';foreach($options as $value=>$text)echo '<option value="'.e($value).'" '.((string)$value===(string)$selected?'selected':'').'>'.e($text).'</option>';echo '</select></label>';}
function attInput(string $name,string $label,string $value='',string $type='text',bool $required=true):void{echo '<label>'.e($label).'<input name="'.e($name).'" type="'.e($type).'" value="'.e($value).'" '.($required?'required':'').'></label>';}
function attForm(string $action):void{echo '<form method="post">';csrf();echo '<input type="hidden" name="action" value="'.e($action).'">';}
function attTutors():array{$out=[];foreach(staff()as $s)if(teaching($s))$out[$s['id']]=$s['name'];return $out;}
function attRooms():array{$out=[];foreach(all('SELECT * FROM classrooms WHERE active=1 ORDER BY room_code')as $r)$out[$r['id']]=$r['room_code'];return $out;}
