staff_id']]):one('SELECT room_code AS name FROM classrooms WHERE id=?',[$d['classroom_id']]);?><tr><td><?=e($d['device_name'])?></td><td><?=e($owner['name']??'')?></td><td><?=e($d['registered_at'])?></td><td><?=e($d['last_seen_at'])?></td><td><?=$d['active']?'Active':'Revoked'?></td><td><?php if($d['active']):attForm('att_revoke');?><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=$d['id']?>"><button class="secondary">Revoke / reset</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endforeach;?></section>
