'].'–'.$t['end_time'])?></small></td><td><?=e($t['room_code'])?></td><td><?=$t['active']?'Active':'Disabled'?><small><?=e(($t['delivery_mode']??'In person').' · Attendance '.(($t['attendance_required']??1)?'required':'not required').(!empty($t['flexible'])?' · Flexible':''))?></small><?php if(academic($user)):?><a href="?page=att_edit&id=<?=$t['id']?>"> Edit</a><?php if($t['active']):attForm('att_disable');?><input type="hidden" name="id" value="<?=$t['id']?>"><button class="secondary">Disable future classes</button></form><?php endif;if($user['role']==='admin'):attForm('att_delete');?><input type="hidden" name="id" value="<?=$t['id']?>"><button class="secondary">Delete unused future schedule</button></form><?php endif;endif;?></td></tr><?php }?></tbody></table></div></section>
<?php elseif($page==='att_settings'&&$user['role']==='admin'):$s=attSettings();?><section class="card"><h2>Attendance Windows</h2><?php attForm('att_settings');?><div class="form-grid"><?php foreach(['early_minutes'=>'Minutes before start allowed','late_minutes'=>'Minutes after start before late','close_minutes'=>'Minutes after start before closed','qr_seconds'=>'QR refresh seconds (30–60)']as $k=>$label)attInput($k,$label,(string)$s[$k],'number');?></div><button>Save settings</button></form></section><section class="card"><h2>Latest audit events</h2><div class="table-wrap"><table><thead><tr><th>When</th><th>Actor</th><th>Event</th><th>Details</th></tr></thead><tbody><?php foreach(all('SELECT a.*,u.name FROM attendance_audit a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.id DESC LIMIT 100')as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e($a['name']??'Device / visitor')?></td><td><?=e($a['event'])?></td><td><?=e($a['details'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif(in_array($page,['att_dashboard','att_my'],true)):
$filters=$_GET;if($page==='att_my'){attRequire(teaching($user));$filters['staff_id']=$user['id'];}$filters['from']=$filters['from']??date('Y-m-d');$filters['to']=$filters['to']??($page==='att_my'?date('Y-m-d',strtotime('+7 days')):date('Y-m-d'));try{$rows=attendanceReport($user,$filters);}catch(RuntimeException $ex){echo '<div class="notice error">'.e($ex->getMessage()).'</div>';return;}$counts=array_count_values(array_column($rows,'status'));?><section class="card"><h2><?=$page==='att_my'?'My Classes & Attendance':'Attendance Dashboard & Reports'?></h2><form class="filters" method="get"><input type="hidden" name="page" value="<?=e($page)?>"><?php attInput('from','From date',$filters['from'],'date');attInput('to','To date',$filters['to'],'date');if($page!=='att_my'){attSelect('staff_id','Tutor',attTutors(),$_GET['staff_id']??'');attSelect('department','Department',array_combine(departments(),departments()),$_GET['department']??'');}attSelect('programme','Programme',array_combine(programmes(),programmes()),$_GET['programme']??'');attSelect('classroom_id','Classroom',attRooms(),$_GET['classroom_id']??'');attSelect('status','Status',array_combine(['Present','Late','Missed','Cancelled','Substituted','Adjusted','Upcoming'],['Present','Late','Missed','Cancelled','Substituted','Adjusted','Upcoming']),$_GET['status']??'');?><button>View report</button><a href="?<?=e(http_build_query(array_merge($filters,['page'=>'att_export'])))?>">Export Excel</a></form><p>Choose one day for a daily report or a month range for a monthly summary. Missed means no recorded confirmation after the configured window. QR confirmation does not measure the whole class duration.</p><div class="stats"><div><small>Scheduled</small><strong><?=count($rows)?></strong></div><div><small>Confirmed / substituted</small><strong><?=($counts['Present']??0)+($counts['Late']??0)+($counts['Substituted']??0)?></strong></div><div><small>Late / missed</small><strong><?=($counts['Late']??0)?> / <?=($counts['Missed']??0)?></strong></div><div><small>Cancelled</small><strong><?=$counts['Cancelled']??0?></strong></div></div><div class="table-wrap"><table><thead><tr><th>Date / timetable</th><th>Tutor / subject</th><th>Room / time</th><th>Confirmed</th><th>Status</th><th>Remarks</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['date'])?><small>#<?=$r['timetable_id']?></small></td><td><?=e($r['tutor'])?><small><?=e($r['subject'])?></small></td><td><?=e($r['room'].' '.$r['start'].'–'.$r['end'])?></td><td><?=e($r['confirmed']?:'—')?></td><td><?=e($r['status'])?></td><td><?=e($r['remarks'])?></td></tr><?php endforeach;?></tbody></table></div>
<?php foreach(['tutor'=>'Tutor-wise summary','department'=>'Department-wise summary','programme'=>'Programme-wise summary','room'=>'Classroom utilization']as $key=>$title):$groups=[];foreach($rows as $r){$label=$r[$key];$groups[$label]??=['classes'=>0,'confirmed'=>0,'minutes'=>0];$groups[$label]['classes']++;$groups[$label]['minutes']+=(strtotime($r['end'])-strtotime($r['start']))/60;if(in_array($r['status'],['Present','Late','Substituted']))$groups[$label]['confirmed']++;}?><details><summary><?=e($title)?></summary><table><thead><tr><th>Group</th><th>Scheduled</th><th>Confirmed</th><th>Scheduled hours</th></tr></thead><tbody><?php foreach($groups as $label=>$g):?><tr><td><?=e($label)?></td><td><?=$g['classes']?></td><td><?=$g['confirmed']?></td><td><?=round($g['minutes']/60,2)?></td></tr><?php endforeach;?></tbody></table></details><?php endforeach;?></section>
<?php if(academic($user)):?><section class="card"><h2>Attendance exception / substitution</h2><p>Use the timetable ID from the report. A reason is required; adjustments are audited. Existing confirmation evidence is retained.</p><?php attForm('att_adjust');?><div class="form-grid"><?php field('timetable_id','Timetable ID','number');field('day','Class date','date');field('status','Status','select',['Present','Late','Missed','Cancelled','Substituted','Adjusted']);attSelect('substitute_id','Substitute (required for Substituted)',attTutors());field('remarks','Reason','textarea');?></div><button>Record adjustment</button></form></section><?php endif;?>
